x_938076_backup_0_backup_scripts.script:
incCount('software');
incCount('hardware');


//var cat = "Software";

function incCount(cat) {
    var gaIncident = new GlideAggregate('incident');
    gaIncident.addQuery('category', cat);
    gaIncident.query();
    while (gaIncident.next()) {
        gs.print(gaIncident.number.toString());
    }
    //gaIncident.addQuery('category', cat);
    gaIncident.addAggregate("COUNT");
    gaIncident.query();
    while (gaIncident.next()) {
        var count = gaIncident.getAggregate('COUNT');
        if (cat == 'software') {
            gs.info('Number of incidents with category Software: ' + count);
        } else if (cat == 'hardware') {
            gs.info('Number of incidents with category hardware: ' + count);
        }
    }

}
